From d54ece5d85ec1527a4864331f8f3e69c58dbd5b5 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 20:20:10 +0100
Subject: [PATCH] logout-greeter: Proceed when the same prompt is requested
 again

Pressing the logout or shutdown shortcut again while the logout screen
was already showing did nothing. Asking for the same prompt a second time
now confirms it right away, instead of waiting for the countdown to end.

BUG: 389896
---
 logout-greeter/greeter.cpp     | 36 +++++++++++++++-------------------
 logout-greeter/greeter.h       |  1 +
 logout-greeter/shutdowndlg.cpp | 23 ++++++++++++++++++++++
 logout-greeter/shutdowndlg.h   |  2 ++
 4 files changed, 42 insertions(+), 20 deletions(-)

diff --git a/logout-greeter/greeter.cpp b/logout-greeter/greeter.cpp
index 3cd962507b..cb0e833eba 100644
--- a/logout-greeter/greeter.cpp
+++ b/logout-greeter/greeter.cpp
@@ -142,41 +142,37 @@ bool Greeter::eventFilter(QObject *watched, QEvent *event)

 void Greeter::promptLogout()
 {
-    if (m_running) {
-        qCWarning(LOGOUT_GREETER) << "promptLogout was called but we were already showing the logout screen; doing nothing";
-        return;
-    }
-    m_shutdownType = ShutdownTypeNone;
-    init();
+    prompt(ShutdownTypeNone);
 }

 void Greeter::promptShutDown()
 {
-    if (m_running) {
-        qCWarning(LOGOUT_GREETER) << "promptShutDown was called but we were already showing the logout screen; doing nothing";
-        return;
-    }
-    m_shutdownType = ShutdownTypeHalt;
-    init();
+    prompt(ShutdownTypeHalt);
 }

 void Greeter::promptReboot()
 {
-    if (m_running) {
-        qCWarning(LOGOUT_GREETER) << "promptReboot was called but we were already showing the logout screen; doing nothing";
-        return;
-    }
-    m_shutdownType = ShutdownTypeReboot;
-    init();
+    prompt(ShutdownTypeReboot);
 }

 void Greeter::promptAll()
+{
+    prompt(ShutdownTypeDefault);
+}
+
+void Greeter::prompt(ShutdownType shutdownType)
 {
     if (m_running) {
-        qCWarning(LOGOUT_GREETER) << "promptAll was called but we were already showing the logout screen; doing nothing";
+        // Asking again for the screen that is already shown, e.g. by pressing
+        // the same shortcut twice, confirms it without waiting
+        if (shutdownType == m_shutdownType && !m_dialogs.isEmpty()) {
+            m_dialogs.constFirst()->proceed();
+        } else {
+            qCWarning(LOGOUT_GREETER) << "A different logout prompt was requested but we were already showing the logout screen; doing nothing";
+        }
         return;
     }
-    m_shutdownType = ShutdownTypeDefault;
+    m_shutdownType = shutdownType;
     init();
 }

diff --git a/logout-greeter/greeter.h b/logout-greeter/greeter.h
index dbb1f98d64..1861e33f8d 100644
--- a/logout-greeter/greeter.h
+++ b/logout-greeter/greeter.h
@@ -38,6 +38,7 @@ public Q_SLOTS:
     void promptAll();

 private:
+    void prompt(ShutdownType shutdownType);
     void quit();
     void adoptScreen(QScreen *screen);

diff --git a/logout-greeter/shutdowndlg.cpp b/logout-greeter/shutdowndlg.cpp
index ce552d3ca0..4b3dc1c40f 100644
--- a/logout-greeter/shutdowndlg.cpp
+++ b/logout-greeter/shutdowndlg.cpp
@@ -68,6 +68,7 @@ KSMShutdownDlg::KSMShutdownDlg(QQmlEngine *engine, ShutdownType sdtype, bool win
     : QQuickView(engine, nullptr)
     , m_result(false)
     , m_windowed(windowed)
+    , m_shutdownType(sdtype)
 {
     // window stuff
     setColor(QColor(Qt::transparent));
@@ -254,6 +255,28 @@ void KSMShutdownDlg::init(const KPackage::Package &package)
     setKeyboardGrabEnabled(true);
 }

+void KSMShutdownDlg::proceed()
+{
+    const bool updatePending = updateTriggered() || upgradeTriggered();
+    switch (m_shutdownType) {
+    case ShutdownTypeNone:
+        slotLogout();
+        break;
+    case ShutdownTypeReboot:
+        updatePending ? slotRebootUpdate() : slotReboot();
+        break;
+    case ShutdownTypeDefault:
+        if (!m_session.canShutdown()) {
+            slotLogout();
+            break;
+        }
+        [[fallthrough]];
+    case ShutdownTypeHalt:
+        updatePending ? slotHaltUpdate() : slotHalt();
+        break;
+    }
+}
+
 void KSMShutdownDlg::slotLogout()
 {
     m_session.requestLogout(SessionManagement::ConfirmationMode::Skip);
diff --git a/logout-greeter/shutdowndlg.h b/logout-greeter/shutdowndlg.h
index a20d43ddc8..9e964d6f98 100644
--- a/logout-greeter/shutdowndlg.h
+++ b/logout-greeter/shutdowndlg.h
@@ -47,6 +47,7 @@ public:

     void init(const KPackage::Package &package);
     bool result() const;
+    void proceed();

 public Q_SLOTS:
     void accept();
@@ -74,6 +75,7 @@ private:
     bool upgradeTriggered() const;

     bool m_windowed = false;
+    ShutdownType m_shutdownType;
     QString m_bootOption;
     QStringList rebootOptions;
     bool m_result : 1;
